    /* NeoSeo Popup Compare - begin */
    public function remove(){
		$json = array();
        $json['result'] = "false";

        $key = array_search($this->request->post['product_id'], $this->session->data['compare']);
        if ($key !== false) {
            unset($this->session->data['compare'][$key]);
            $json['result'] = "true";
        }

        $this->load->model("module/neoseo_popup_compare");
        $json = $this->model_module_neoseo_popup_compare->getCompare($this->request->post['product_id'], $json);

        $this->response->setOutput(json_encode($json));
    }
    /* NeoSeo Popup Compare - end */
